package com.emp.ems;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/v1") @Transactional(readOnly=true)
public class PeopleController{private final EmployeeRepository employees;private final TaskRepository tasks;private final EventRepository events;private final PasswordEncoder encoder;PeopleController(EmployeeRepository employees,TaskRepository tasks,EventRepository events,PasswordEncoder encoder){this.employees=employees;this.tasks=tasks;this.events=events;this.encoder=encoder;}record Create(@NotBlank @Size(max=100)String name,@NotBlank @Email @Size(max=254)String email,@NotBlank @Size(max=100)String title,@NotBlank @Size(max=60)String department,@NotBlank @Size(min=12,max=72)String password){}record Candidate(UUID id,String name,String title,int avatar,long completed,int total,List<OnboardingTask.View> tasks){}record TaskUpdate(@NotNull Boolean done){}
 @GetMapping("/admin/employees")PageResponse<Employee.View> employees(@RequestParam(defaultValue="")String search,Pageable page){return PageResponse.of(employees.search(search.substring(0,Math.min(100,search.length())),bounded(page,"name",false)).map(Employee::view));}
 @PostMapping("/admin/employees")@ResponseStatus(HttpStatus.CREATED)@Transactional Employee.View create(@Valid @RequestBody Create input){if(employees.existsByEmailIgnoreCase(input.email().trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"An employee with this email already exists.");Employee e=new Employee();e.name=input.name().trim();e.email=input.email().trim().toLowerCase(Locale.ROOT);e.title=input.title().trim();e.department=input.department().trim();e.passwordHash=encoder.encode(input.password());employees.save(e);seedTasks(e);return e.view();}
 @GetMapping("/admin/events")PageResponse<WorkspaceEvent.View> events(Pageable page){return PageResponse.of(events.findAll(bounded(page,"date",false)).map(WorkspaceEvent::view));}
 @GetMapping("/admin/onboarding")PageResponse<Candidate> onboarding(Pageable page){Page<Employee> people=employees.findByStatus("Onboarding",bounded(page,"name",false));if(people.isEmpty())return PageResponse.of(people.map(e->candidate(e,List.of())));var grouped=tasks.findByEmployeeIdInOrderBySortOrder(people.map(e->e.id).getContent()).stream().collect(java.util.stream.Collectors.groupingBy(t->t.employee.id));return PageResponse.of(people.map(e->candidate(e,grouped.getOrDefault(e.id,List.of()))));}
 @GetMapping("/employee/tasks")Candidate ownTasks(@AuthenticationPrincipal CurrentUser user){return candidate(employees.findById(user.id()).orElseThrow(),tasks.findByEmployeeIdOrderBySortOrder(user.id()));}
 @PatchMapping({"/admin/tasks/{id}","/employee/tasks/{id}"})@Transactional OnboardingTask.View task(@PathVariable UUID id,@Valid @RequestBody TaskUpdate update,@AuthenticationPrincipal CurrentUser user){OnboardingTask t=tasks.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Task not found."));if(!user.role().equals("ADMIN")&&!t.employee.id.equals(user.id()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This task belongs to another employee.");t.done=update.done();return t.view();}
 Candidate candidate(Employee e,List<OnboardingTask> list){return new Candidate(e.id,e.name,e.title,e.avatar,list.stream().filter(t->t.done).count(),list.size(),list.stream().map(OnboardingTask::view).toList());}
 void seedTasks(Employee e){String[] labels={"Complete your profile","Sign employment documents","Meet your team","Set up your workspace","Read the team handbook","Explore our product","Meet your onboarding buddy","Complete security training","Set your first goals","Have a manager check-in"};for(int i=0;i<labels.length;i++){OnboardingTask t=new OnboardingTask();t.employee=e;t.label=labels[i];t.sortOrder=i;tasks.save(t);}}
 static Pageable bounded(Pageable page,String field,boolean descending){return PageRequest.of(Math.max(0,page.getPageNumber()),Math.min(100,Math.max(1,page.getPageSize())),descending?Sort.by(field).descending():Sort.by(field));}
}
